--[[
Proyecto Super Pang Hitbox v0.3

Esta version ya cuenta con muchas caracteristicas principales implementadas
aunque aun tiene detalles no pulidos

- v0.3 implementa la deteccion de items dentro de bloques, 
    deteccion de premios garantizados segun N ataques, 
    prediccion del siguiente item al atacar un globo 
    y reconocer cuando esta habilitada la estrella de la suerte 
    en un nivel y bien calcular cuantos eventos faltan
    para que al cargar un nivel el contador este disponible.

    Todas estas opciones son desactivables con botones colocados debajo 
]]

Button = {}
Button.__index = Button
Button.instances = {}

function Button.new(options)
    options = options or {}

    local self = setmetatable({}, Button)

    self.x = options.x or 10
    self.y = options.y or 10
    self.width = options.width or 100
    self.height = options.height or 25

    self.text = options.text or "Button"

    self.color = options.color or "0x333333FF"
    self.hoverColor = options.hoverColor or "0x555555FF"

    self.outlineColor = options.outlineColor or "0xFFFFFFFF"
    self.textColor = options.textColor

    self.visible = true
    self.enabled = true
    self.hovered = false

    self.onClick = options.onClick

    table.insert(Button.instances, self)

    return self
end

function Button:isInside(mouseX, mouseY)
    return mouseX >= self.x and mouseX <= self.x + self.width and
        mouseY >= self.y and mouseY <= self.y + self.height
end

function Button:draw()
    if not self.visible then
        return
    end

    local bgColor = self.color

    if self.hovered then
        bgColor = self.hoverColor
    end

    gui.box(self.x, self.y, self.x + self.width, self.y + self.height, bgColor, self.outlineColor)

    gui.text(self.x + 5, self.y + math.floor((self.height - 8) / 2), self.text)
end

function Button:click()
    if self.onClick then
        self.onClick(self)
    end
end


Button.lastMousePressed = false

function Button.update()
    local mouse = input.get()

    local mouseX = mouse.xmouse
    local mouseY = mouse.ymouse

    local mousePressed = mouse.leftclick or false

    local justPressed = mousePressed and not Button.lastMousePressed

    for _, button in ipairs(Button.instances) do
        button.hovered = button.enabled and button.visible and button:isInside(mouseX, mouseY)
    end

    if justPressed then
        for _, button in ipairs(Button.instances) do
            if button.enabled and button.visible and button.hovered then
                button:click()
                break
            end
        end
    end

    Button.lastMousePressed = mousePressed

    for _, button in ipairs(Button.instances) do
        button:draw()
    end

end

