local function drawBalloonHitbox(p)
    local xraw = memory.readbyte(p + 0x09) +
                memory.readbyte(p + 0x0A) * 256 +
                memory.readbyte(p + 0x0B) * 65536
    local x = math.floor(xraw / 256) - 64
    local collisionX = memory.readbyte(p + 0x1B)
    local y = memory.readbyte(p + 0x0D) - 8
    local size = memory.readbyte(p + 0x16)

    local tabla
    local center
    local count

    if size == 1 then
        if enableHitBox then
            gui.box(
                x - 2,
                y - 4,
                x + 2,
                y + 3,
                0xFF000080
            )

            -- Dibujando Hitbox contra el jugador
            gui.box(
                x - 0x11 + 0x08,
                y - 0x0C,
                x + 0x08,
                y + (0x1C - 0x0C),
                0x00000000,
                0xFFFF00FF
            )
        end
        return
    elseif size == 2 then
        if enableHitBox then
            gui.box(
                x - 4,
                y - 8,
                x + 4,
                y + 7,
                0xFF000080
            )

            -- Dibujando Hitbox contra el jugador
            gui.box(
                x - 0x15 + 0x0A,
                y - 0x0E,
                x + 0x0A,
                y + (0x20 - 0x0E),
                0x00000000,
                0xFF00FFFF
            )
        end

        if nextReward ~= nil and enableBalloonReward then
            gui.opacity(0.5)
            gui.gdoverlay(x-8, y-8, OBJECT_GD[nextReward])
            gui.opacity(1.0)
        end

        return
    elseif size == 4 then
        tableData = HITBOX_SIZE4
        center = 8
        count = 17
    elseif size == 8 then
        tableData = HITBOX_SIZE8
        center = 12
        count = 25
    elseif size == 16 then
        tableData = HITBOX_SIZE16
        center = 16
        count = 33
    else
        return
    end

    if enableHitBox then
        -- Dibujando casos 4 8 16
        local boxCenterX = collisionX * 2 - 64
        for dx = 0, count - 1 do
            local v1 = tableData[dx + 1][1]
            local v2 = tableData[dx + 1][2]

            local boxX = boxCenterX + ((dx - center) * 2)
            local top = y - v1
            local bottom = y + (v2 - v1)

            gui.box(
                boxX-1,
                top,
                boxX+0,
                bottom,
                0x00000000,
                0xFF000080
            )

        end

        -- Dibujando Hitbox contra el jugador
        if size == 4 then
            gui.box(
                x - 0x1F + 0x0F,
                y - 0x12,
                x + 0x0F,
                y + (0x28 - 0x12),
                0x00000000,
                0xFFFFFFFF
            )
        elseif size == 8 then
            gui.box(
                x - 0x2D + 0x16,
                y - 0x1A,
                x + 0x16,
                y + (0x38 - 0x1A),
                0x00000000,
                0x00FF00FF
            )
        elseif size == 16 then
            gui.box(
                x - 0x1D,
                y - 0x1E,
                x + 0x1C,
                y + (0x40 - 0x1E),
                0x00000000,
                0xFF0000FF
            )
        end
    end

    if nextReward ~= nil and enableBalloonReward then
        if liveUse and nextReward == 0x0E then
        else
            gui.opacity(0.5)
            gui.gdoverlay(x-8, y-8, OBJECT_GD[nextReward])
            gui.opacity(1.0)
        end
    end

end

local function drawHarpoonHitbox(p)
    if not enableHitBox then
        return
    end

    local collisionX = memory.readbyte(p + 0x1B)
    local x = collisionX * 2 - 64
    local yCurrent = memory.readbyte(p + 0x0D) - 8
    local yReference = memory.readbyte(p + 0x0E) - 8
    local top = math.min(yCurrent, yReference)
    local bottom = math.max(yCurrent, yReference)

    gui.box(
        x,
        top,
        x ,
        bottom,
        0xFF0000FF
    )
end

local function drawPlayerBalloonHitbox(p)
    if not enableHitBox then
        return
    end

    local xraw = memory.readbyte(p + 0x09) +
                memory.readbyte(p + 0x0A) * 256 +
                memory.readbyte(p + 0x0B) * 65536
    local x = math.floor(xraw / 256) - 64
    local y = memory.readbyte(p + 0x0D) - 8

    gui.box(
        x - 0x11 + 0x08,
        y - 0x0C,
        x + 0x08,
        y + (0x1C - 0x0C),
        0x00000000,
        0xFFFF00FF
    )

end

local function drawLadderHitbox(p)
    if not enableHitBox then
        return
    end

    local xraw = memory.readbyte(p + 0x09) +
                memory.readbyte(p + 0x0A) * 256 +
                memory.readbyte(p + 0x0B) * 65536
    local x = math.floor(xraw / 256) - 64
    local y = memory.readbyte(p + 0x0D) - 8

    local ladderY1 = memory.readbyte(p + 0x0C) - 8 - 0x10
    local ladderY2 = memory.readbyte(p + 0x0D) - 8 - 0x10
    local ladderTop = math.min(ladderY1, ladderY2)
    local ladderBottom = math.max(ladderY1, ladderY2)

    gui.box(
        x - 0x9,
        ladderTop,
        x + 0x9,
        ladderBottom,
        0x00000000,
        0xFFFF00FF
    )
end

local function drawExperimentalBox(p)
    if not enableHitBox then
        return
    end

    local xraw = memory.readbyte(p + 0x09) +
        memory.readbyte(p + 0x0A) * 256 +
        memory.readbyte(p + 0x0B) * 65536
    local x = math.floor(xraw / 256) - 64
    local y = memory.readbyte(p + 0x0D) - 8

    local w = 16
    local h = 16

    local left   = x - math.floor(w / 2)
    local right  = x + math.floor(w / 2)
    local top    = y - math.floor(h / 2)
    local bottom = y + math.floor(h / 2)

    gui.box(
        left,
        top,
        right,
        bottom,
        0xFF000080
    )
end

local function drawLevelCollisionGrid()
    local BASE = 0xC800
    local BASE2 = 0xF000
    local BASE3 = 0xD000
    local COLS = 64
    local ROWS = 32
    local CELL = 8

    local ORIGIN_X = -64
    local ORIGIN_Y = -8

    local rewards = REWARDS[level]
    gridRewards = {}

    for row = 0, ROWS - 1 do
        for col = 0, COLS - 1 do

            if (row > 26) then
                break
            end

            local id = memory.readbyte(BASE + row * 0x40 + col)
            local value = memory.readbyte(BASE2 + row * 0x40 + col)

            -- id detectados como colisionables
            if id == 0x1F or id == 0x0D or value ~= 0 then
                local x1 = ORIGIN_X + col * CELL
                local y1 = ORIGIN_Y + row * CELL
                local x2 = x1 + CELL
                local y2 = y1 + CELL

                local color
                local bcolor

                if id == 0x1F then
                    color = 0x00A0FF80
                    bcolor = color
                elseif id == 0x0D then
                    color = 0xFF000080
                    bcolor = color
                elseif value ~= 0 then
                    color = 0x00000000
                    bcolor = 0xFFFFFFFF
                end

                if enableHitBox then
                    gui.box(x1,y1,x2,y2,color,bcolor)
                end

                -- Rastrear el objeto oculto adentro, 0xFF/0xFD/0xFE/0xFC son estruturas indestructibles
                if value ~= 0xFF and value ~= 0xFD and value ~= 0xFE and value ~= 0xFC then
                    local flag = (math.floor(value / 8) % 8) * 8
                    local name = nil

                    local id = nil

                    if flag == 0x08 then
                        name = "BONUS"
                        id = 0xFF
                    elseif flag >= 0x10 and flag <= 0x38 then
                        name = OBJECT_NAMES[rewards[math.floor(flag / 8) - 1]]
                        id = rewards[math.floor(flag / 8) - 1]
                    end

                    if id then

                        local v2 = memory.readbyte(BASE3 + row * 0x80 + col * 2)
                        local xf = x1
                        local yf = y1

                        if v2 == 0xA6 then
                            for y = row + 1, ROWS - 1 do
                                local belowV2 = memory.readbyte(BASE3 + y * 0x80 + col * 2)
                        
                                if belowV2 == 0xB7 then
                                    yf = yf + 8
                                    break
                                end

                                yf = yf + 8
                            end

                            gridRewards[#gridRewards+1] = {x = x1, y = y1, xf = xf+8, yf = yf+8, name = name, id = id}
                        elseif v2 ~= 0xB6 and v2 ~= 0xA4 and v2 ~= 0xA7 and v2 ~= 0xB7 then
                            for x = col + 1, COLS - 1 do
                                local nextValue = memory.readbyte(BASE2 + row * 0x40 + x)
                            
                                if nextValue == 0x00 or
                                    nextValue == 0xFF or
                                    nextValue == 0xFD or
                                    nextValue == 0xFE or 
                                    nextValue > 10 then
                                    break
                                end

                                xf = xf + 8
                            end

                            gridRewards[#gridRewards+1] = {x = x1, y = y1, xf = xf+8, yf = yf+8, name = name, id = id}
                        end

                        
                    end

                end


            end
        end
    end

end

local function calcNextRNG(n)
   local e146 = n % 256
   local t = (n * 3) % 65536

   local nuevo147 = math.floor(t / 256)
   local nuevo146 = (e146 + nuevo147) % 256

   return nuevo147 * 256 + nuevo146
end

local function predictNextRandomReward()
    -- Primero el premio garantizado
    if rewardN == 1 and rewardId ~= 0 then
        return rewardId
    end

    -- Sino, se predice el premio aleatorio
    local e146 = memory.readbyte(0xE146)
    local e147 = memory.readbyte(0xE147)
    local n = e147 * 256 + e146
    local next = calcNextRNG(n)
    local nextE147 = math.floor(next / 256)
    local nextE146 = next % 256

    local index = nextE146 % 32
    local dropTable = DROP_TABLES[level]
    local id = dropTable[index + 1]

    if id == 0 then
        return nil
    else
        return (id - 2) % 256
    end

end

level = nil
nextReward = nil
rewardN = 0
rewardId = 0
gridRewards = {}
bonusUse = false
liveUse = false

local cache = nil
local ultimoN = nil
local oportunidades = {}

local function createSequence(inicial)
    local estados = {}
    local indices = {}

    local actual = inicial

    while indices[actual] == nil and #estados < 65536 do
        local indice = #estados + 1

        estados[indice] = actual
        indices[actual] = indice

        actual = calcNextRNG(actual)
    end

    local inicioCiclo = indices[actual]

    if not inicioCiclo then
        return nil
    end

    local longitudCiclo = #estados - inicioCiclo + 1
    local cerosCiclo = 0

    for i = inicioCiclo, #estados do
        local nextIndice

        if i < #estados then
            nextIndice = i + 1
        else
            nextIndice = inicioCiclo
        end

        if estados[nextIndice] % 256 == 0 then
            cerosCiclo = cerosCiclo + 1
        end

    end

    return {
        estados = estados,
        indices = indices,
        inicio = inicioCiclo,
        longitud = longitudCiclo,
        ceros = cerosCiclo
    }

end

local function predecirDesde(n, cantidad)

    if not cache or not cache.indices[n] then
        cache = createSequence(n)
    end

    local resultados = {}

    if not cache then
        return resultados
    end

    local estados = cache.estados
    local indice = cache.indices[n]

    if not indice then
        return resultados
    end

    local hastaCiclo = math.max(0, cache.inicio - indice)

    local limite = hastaCiclo

    if cache.ceros > 0 then
        limite = limite + cache.longitud * math.ceil(cantidad / cache.ceros)
    end

    local j = indice

    for evento = 1, limite do

        local siguienteIndice

        if j < #estados then
            siguienteIndice = j + 1
        else
            siguienteIndice = cache.inicio
        end

        local antes = estados[j]
        local despues = estados[siguienteIndice]

        if despues % 256 == 0 then
            resultados[#resultados + 1] = {
            evento = evento,
            antes = antes,
            despues = despues
            }

            if #resultados >= cantidad then
            break
            end

        end

        j = siguienteIndice

    end

    return resultados

end


