gui.register(function()
    gui.clearuncommitted()

    Button.update()

    local ingameplay = memory.readbyte(0xe179) == 1
    local instage = memory.readbyte(0xc041) == 1
    local inending = memory.readbyte(0xe09d) == 1
    level = memory.readbyte(0xe099) + 1

    rewardN = memory.readbyte(0xE0BE) or 0
    rewardId = memory.readbyte(0xE0BF) or 0
    local bonusCount = memory.readbyte(0xE0C0) or 0
    local bonusUse = memory.readbyte(0xE0C7) == 1
    bonusUse = memory.readbyte(0xE0C8) == 1
    liveUse = memory.readbyte(0xE0C9) == 1
    local starCount = memory.readbyte(0xE0CD) or 0
    local starUsed = memory.readbyte(0xE0CC) == 2

    local e146 = memory.readbyte(0xE146)
    local e147 = memory.readbyte(0xE147)
    local n = e147 * 256 + e146

    if n ~= ultimoN then
        oportunidades = predecirDesde(n, 1)
        ultimoN = n
    end


    if ingameplay == true and instage == true and inending == false then

        --gui.box(0, 0, 500, 500, 0x000000FF)

        local pointer = 0xE080 -- Inicio puntero de deteccion de objetos

        nextReward = predictNextRandomReward()

        -- aun una suposicion
        -- E200 ─────────────── Jugador 1
        -- E280 ─────────────── Jugador 2
        -- E380 ─────────────── arpón
        -- E780 ─────────────── tabla 8 × 0x10
        -- E800 ─────────────── escalera
        -- E8C0 ─────────────── tabla 4 × 0x20
        -- EA00 ─────────────── otra estructura
        -- F07F ─────────────── fin del rango antiguo

        for i = 0, 255 do

            local p = pointer + i * 0x10 -- 0x10 o 0x20 es posible que la diferencia entre objetos sea dinamico

            local active = memory.readbyte(p + 0x00) == 1

            if active then

                local xraw = memory.readbyte(p + 0x09) +
                            memory.readbyte(p + 0x0A) * 256 +
                            memory.readbyte(p + 0x0B) * 65536
                local x = math.floor(xraw / 256) - 64
                local y = memory.readbyte(p + 0x0D) - 8

                local size = memory.readbyte(p + 0x16)

                --[[En pantalla se necesita hacer una correccion xreal-64 y yreal-8
                para que el dibujo cuadre con lo que aparece en pantalla
                debe hacerse porque los elementos de camara comienzan por el grid 8,2 y cada grid mide 8x8
                ]]

                -- Si no es un globo, no dibuja nada
                drawBalloonHitbox(p)

                if p >= 0xE200 and p < 0xE300 then
                    -- Jugador
                    drawPlayerBalloonHitbox(p)
                elseif p >= 0xE380 and p < 0xE440 then
                    -- Arpon
                    drawHarpoonHitbox(p)
                elseif p >= 0xE800 and p < 0xE880 then
                    -- Escalera
                    drawLadderHitbox(p)
                elseif size==0 then
                    -- Otros objetos
                    drawExperimentalBox(p)
                end

                -- Punto central para todos
                if enableHitBox then
                    gui.box(x, y, x+1, y+1, 0xFFFFFFFF)
                end


            end

        end

        pointer = 0xF900 -- Inicio puntero de tabla secundario para deteccion de items

        for i = 0, 20 do
            local p = pointer + i * 0x20
            local active = memory.readbyte(p + 0x00) == 1

            if active then
                -- aun una suposicion
                local state = memory.readbyte(p + 0x02) -- A0=en caida D3=apoyado FC=parpadeo
                local time = memory.readbyte(p + 0x04) -- B4 primer conteo, 5A segundo conteo

                local xraw = memory.readbyte(p + 0x09) +
                            memory.readbyte(p + 0x0A) * 256 +
                            memory.readbyte(p + 0x0B) * 65536
                local x = math.floor(xraw / 256) - 64
                local y = memory.readbyte(p + 0x0D) - 8

                if enableHitBox then
                    gui.box(
                        x-0x11,
                        y-0x11,
                        x+0x11,
                        y+0x11,
                        0xFF000080
                    )
                end

                local w = 16
                local h = 16

                local top    = y - math.floor(h / 2)
                local bottom = y + math.floor(h / 2)

                if enableHitBox then
                    gui.box(
                        x,
                        top,
                        x,
                        bottom,
                        0xFFFF00FF
                    )

                    if state==0xD3 then
                        gui.text(x-(0x11/2), y-0x11-8, time)
                    elseif state==0xFC then
                        gui.text(x-(0x11/2), y-0x11-8, time, 0xFF0000FF)
                    end
                end

            end

        end

        drawLevelCollisionGrid()

        if enableGridReward then
            for _, reward in ipairs(gridRewards) do
                if bonusUse and reward.id == 0xFF then
                elseif liveUse and reward.id == 0x0E then
                else

                    gui.opacity(0.5)
                    gui.gdoverlay((reward.x + reward.xf) / 2 - 8, (reward.y + reward.yf) / 2 - 8, OBJECT_GD[reward.id])
                    gui.opacity(1.0)
                end
            end
        end

        local ry = 10

        if enableCountReward then
            if bonusCount > 0 and not bonusUse then
                gui.gdoverlay(384/2 - 16, ry, OBJECT_GD[0xFF])
                gui.text(384/2+2, ry+6, bonusCount, 0xFFFFFFFF)
                ry = ry + 18
            end

            if not starUsed and level < 0x23 then
                if starCount > 0 then
                    gui.gdoverlay(384/2 - 16, ry, OBJECT_GD[0x10])
                    gui.text(384/2+2, ry+6, starCount, 0xFFFF00FF)
                elseif enablePredictStar then

                    if #oportunidades > 0 then
                        local p = oportunidades[1]
                        gui.gdoverlay(10, 10, OBJECT_GD[0x10])
                        gui.text(30, 14, string.format("%d eventos", p.evento), 0xFFFF00FF)
                    else
                        -- No hay oportunidades
                    end

                end
            end


            

        end

    end

end)